import { useState } from 'react';
import type { AssemblyData, AssemblyStep } from '../types';
import type { ImageResult } from '../lib/imageGen';
import { RobotDiagram } from './robot/RobotDiagram';
import { ExplodedView } from './ExplodedView';

export interface IllustrationProps {
  data: AssemblyData;
  step: AssemblyStep;
  image?: ImageResult;
  imageLoading?: boolean;
  imageAvailable?: boolean;
  onGenerateImage?: () => void;
  /** Exploded-view asset generated by the teardown skill (available only for a matching robot). */
  explodedAvailable?: boolean;
  explodedUrl?: string;
  /** Controlled on/off state for the exploded view — persists across steps (owned by App). */
  explodedOn?: boolean;
  onToggleExploded?: () => void;
  /** Extra part id to highlight (e.g. when the AI assistant mentions a component). */
  extraHighlight?: string | null;
}

/**
 * The large central illustration for a stage. Shows the AI-generated image
 * (when available) with SVG callout overlays on top, otherwise the reusable
 * SVG schematic diagram. When a teardown-skill exploded view exists for this
 * robot, the user can switch to it; components of the current step are
 * highlighted via their BOM-matching data-item groups.
 */
export function Illustration({ data, step, image, imageLoading, imageAvailable, onGenerateImage, explodedAvailable, explodedUrl, explodedOn, onToggleExploded, extraHighlight }: IllustrationProps) {
  const [forceDiagram, setForceDiagram] = useState(false);
  const imgSrc = image?.url ?? image?.dataUrl;
  const showImage = Boolean(imgSrc) && !forceDiagram && !image?.error;
  const canExplode = Boolean(explodedAvailable && explodedUrl);
  // Exploded view is the default when available; the toggle is a persistent on/off.
  const showExploded = Boolean(canExplode && explodedOn !== false);
  // Merge the assistant-mentioned part into the active set for highlighting.
  const activeIds = extraHighlight && !step.component_ids.includes(extraHighlight)
    ? [...step.component_ids, extraHighlight]
    : step.component_ids;

  return (
    <div className="illustration-frame">
      {imageLoading && (
        <div className="illustration-loading">
          <span className="spinner" aria-hidden /> Generating illustration…
        </div>
      )}
      {showExploded && canExplode ? (
        <ExplodedView svgUrl={explodedUrl as string} installedIds={step.installed_components} activeIds={activeIds} />
      ) : showImage ? (
        <div className="illustration-with-overlay">
          <img src={imgSrc} alt={`AI illustration for step ${step.number}: ${step.title}`} draggable={false} />
          <div className="illustration-overlay">
            <RobotDiagram
              parts={data.parts}
              installedIds={step.installed_components}
              activeIds={activeIds}
              stepNumber={step.number}
              totalSteps={data.steps.length}
              overlayOnly
            />
          </div>
        </div>
      ) : (
        <RobotDiagram
          parts={data.parts}
          installedIds={step.installed_components}
          activeIds={activeIds}
          stepNumber={step.number}
          totalSteps={data.steps.length}
        />
      )}
      {image?.error && <p className="illustration-error">{image.error} Showing SVG diagram.</p>}
      <div className="illustration-toolbar">
        {canExplode && (
          <button
            type="button"
            className={`btn btn-small ${showExploded ? 'btn-primary' : 'btn-ghost'}`}
            onClick={onToggleExploded}
            aria-pressed={showExploded}
            title={showExploded ? 'Turn off exploded view' : 'Turn on exploded view'}
          >
            {showExploded ? '💥 Exploded view: ON' : '💥 Exploded view: OFF'}
          </button>
        )}
        {!showExploded && imageAvailable && onGenerateImage && (
          <button type="button" className="btn btn-ghost btn-small" onClick={onGenerateImage} disabled={imageLoading}>
            {imgSrc ? '↻ Regenerate illustration' : '✨ Generate AI illustration'}
          </button>
        )}
        {!showExploded && showImage && (
          <button type="button" className="btn btn-ghost btn-small" onClick={() => setForceDiagram(true)}>
            Show SVG diagram
          </button>
        )}
        {!showExploded && !showImage && imgSrc && (
          <button type="button" className="btn btn-ghost btn-small" onClick={() => setForceDiagram(false)}>
            Show AI illustration
          </button>
        )}
        <span className="illustration-mode">
          {showExploded ? 'Teardown exploded view (BOM labels, current step highlighted)' : showImage ? 'AI illustration + SVG callouts' : 'SVG schematic diagram'}
        </span>
      </div>
      {data.illustrative && !showImage && !showExploded && <span className="illustrative-badge">Illustrative — not verified construction guidance</span>}
    </div>
  );
}
